import * as http from 'node:http';
async function raw(port: number, method: string, path: string): Promise<string> {
  const res = await fetch('http://127.0.0.1:' + port + path, { method });
  const h: string[] = [];
  res.headers.forEach((v: string, k: string) => { if (k !== 'date' && k !== 'connection' && k !== 'keep-alive') h.push(k + ': ' + v); });
  return res.status + ' ' + h.sort().join('|') + ' body=' + JSON.stringify(await res.text());
}
async function main(): Promise<void> {
  const srv = http.createServer(async (req, res) => {
    if (req.url === '/204') { res.writeHead(204, { 'x-a': '1' }); res.end(); return; }
    if (req.url === '/304') { res.writeHead(304, { etag: 'e' }); res.end(); return; }
    if (req.url === '/len') { res.writeHead(200, { 'content-length': '5' }); res.end(req.method === 'HEAD' ? undefined : 'hello'); return; }
    if (req.url === '/async') { await new Promise<void>((r) => setTimeout(() => r(), 5)); res.writeHead(200, { 'x-a': '1' }); res.end(req.method === 'HEAD' ? undefined : 'hello'); return; }
    res.writeHead(200, { 'content-type': 'text/plain' });
    res.end(req.method === 'HEAD' ? undefined : 'hello');
  });
  await new Promise<void>((r) => srv.listen(0, '127.0.0.1', () => r()));
  const port = (srv.address() as any).port;
  for (const [m, p] of [['HEAD', '/'], ['GET', '/'], ['HEAD', '/len'], ['GET', '/len'], ['HEAD', '/async'], ['GET', '/async'], ['GET', '/204'], ['GET', '/304']]) {
    console.log(m, p, await raw(port, m, p));
  }
  srv.close();
}
